//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//#include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDINS15800.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_5);


    //PanelToGroupBox(panel_2);
    //PanelToGroupBox(panel_3);
    //PanelToGroupBox(panel_4);
    //PanelToGroupBox(panel_6);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    ins_combo_set(dts_CurrTpCd, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02475"); // 발행통화
    ins_combo_set(dts_DomFornIsuTpCd, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03407"); // 발행통화

};


/**
 *  기본값 세팅.
 */
scwin.fn_SetDefaultVal = function() {
    txb_SRCH_ISUR_CD.setValue("GB035");
    txb_SRCH_ISUR_NM.setValue("국고채권");
    $c.stf.showObj(panel_7, false);
    $c.stf.showObj(txb_SRCH_ISUR_NM, false);
};



/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function(pFg) {
    if (pFg == "ins_SearchDetail1") {
        dts_StripInfo.removeAll();
        return;
    } else if (pFg == "ins_SearchDetail2") {
        dts_IntInfo.removeAll();
        return;
    }
    dts_ApplInfo.removeAll();
    dts_StripInfo.removeAll();
    dts_IntInfo.removeAll();
};


/**
 * 신청정보 조회(신청마스터 조회)
 */
scwin.ins_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("ins_Search");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_Search")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_ApplInfo);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdStripInfoInquiry" + "&outputMessageId=INS_LIST_STDCD_STRIP_INFO_INQUIRY" + "&param01=" + $c.stf.getObjectValue(txb_SRCH_STD_CD) + "&param02=" + $c.stf.getObjectValue(txb_SRCH_OBJ_ISUR_CD) + "&param03=" + $c.stf.getObjectValue(txb_SRCH_OBJ_ISU_NM) + "&param04=" + $c.stf.getObjectValue(txb_SRCH_ISUR_CD) + "&param05=" + $c.stf.getObjectValue(edt_FROM_ISU_DD) + "&param06=" + $c.stf.getObjectValue(edt_TO_ISU_DD) + "&param07=" + $c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) + "&param08=" + $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD);
    dts_ApplInfo.DataID = encodeURI(url);
    dts_ApplInfo.Reset();
};


/**
 * 스트립-상세조회( 원본채권, 원금분리채권 정보 조회)
 */
scwin.ins_SearchDetail1 = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("ins_SearchDetail1");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_SearchDetail1")) {
        return;
    }

    // Lodaing~~~ 표시
    //ShowWin(panel_1);

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.readStdCdStripInfoMngView" + "&outputMessageId=INS_READ_STDCD_STRIP_INFO_MNG_VIEW" + "&param01=" + dts_ApplInfo.getCellData(dts_ApplInfo.getRowPosition(), "OBJ_ISU_CD");
    dts_StripInfo.DataID = encodeURI(url);
    dts_StripInfo.Reset();
};


/**
 * 스트립-상세조회(이자분리채권 정보 조회) 
 */
scwin.ins_SearchDetail2 = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("ins_SearchDetail2");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_SearchDetail2")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(panel_1);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.readStdCdStripInfoMngViewInfo" + "&outputMessageId=INS_READ_STDCD_STRIP_INFO_MNG_VIEW_INFO" + "&param01=" + dts_ApplInfo.getCellData(dts_ApplInfo.getRowPosition(), "OBJ_ISU_CD");
    dts_IntInfo.DataID = encodeURI(url);
    dts_IntInfo.Reset();
};


/**
 * 첨부파일
 */
scwin.ins_ReadStdCdCdInfoFile = function() {
    txb_param1.setValue(dts_StripInfo.getCellData(1, "STD_CD_APPL_ID")); // 표준코드 신청 ID  
    txb_param2.setValue("2");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == undefined) {
        return true;
    }
    if (pGubun == "ins_Search") {
        if ($c.stf.getObjectValue(txb_SRCH_ISUR_CD) == "") {
            $c.win.alert("발행기관 코드를 확인하세요.");
            txb_SRCH_ISUR_CD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_ISU_DD, edt_TO_ISU_DD) == false) {
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) == false) {
            return false;
        }
    } else if (pGubun == "ins_Save") {
        //if( getObjectValue(txb_ISUR_CD) == "" ){

        //	alert("발행기관 코드를 확인하세요.");

        //	txb_ISUR_CD.focus();

        //	return false;

        //}

    }
    return true;
};


/**
 * 발생기관 팝업에서 값 받음.
 */
scwin.fn_GetParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드      
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.gform_onload = function() {
    scwin.fn_Init();
    var arrObjectApct = [txb_APCT_NM, txb_APCT_FAX_NO, txb_APCT_TEL_NO, txb_APCT_INNR_NO];
    for (var i = 0; i < arrObjectApct.length; i++) {
        fn_apct_delchar(arrObjectApct[i]);
    }
    txb_SRCH_STD_CD.focus();
};
scwin.dts_ApplInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_ApplInfo);
    $c.stf.alert_error(dts_ApplInfo);

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_ApplInfo_OnLoadCompleted = function(rowcount) {
    if (dts_ApplInfo.errorMsg) {
        $c.win.alert(dts_ApplInfo.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_ApplInfo);

    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn_temp("no_data");
    } else {
        fn_CtrlBtn_temp("update");
    }

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_ApplInfo_OnRowPosChanged = function(row) {
    if (row > 0) {
        // 상세조회
        scwin.ins_SearchDetail1();
    }
};
scwin.dts_StripInfo_OnLoadError = function() {
    //CloseWin(-1, panel_1);
    $c.stf.alert_error(dts_StripInfo);
};
scwin.dts_StripInfo_OnLoadCompleted = function(rowcount) {
    if (dts_StripInfo.errorMsg) {
        $c.win.alert(dts_StripInfo.errorMsg);
    }
    //CloseWin(-1, panel_1);

    // 이자분리채권 조회
    scwin.ins_SearchDetail2();
};
scwin.dts_IntInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, panel_1);
    $c.stf.alert_error(dts_IntInfo);
};
scwin.dts_IntInfo_OnLoadCompleted = function(rowcount) {
    if (dts_IntInfo.errorMsg) {
        $c.win.alert(dts_IntInfo.errorMsg);
    }
    $c.cm.CloseWin(-1, panel_1);
};
scwin.btn_file_onclick = function() {
    // 첨부파일
    scwin.ins_ReadStdCdCdInfoFile();
};
scwin.btn_prcnm_onclick = function() {
    //txb_param1.value = txb_OBJ_ISU_CD.value; // 대상표준코드 
    txb_param1.setValue(txb_STD_CD.getValue()); // 분리표준코드 
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS93300", "표준코드 처리자 조회", "620", "420");
};
scwin.img_STRIP_ISU_DD_onclick = function() {
    popUpCalendar2(edt_STRIP_ISU_DD);
};
scwin.img_STRIP_MAJAGNT_INST_CD_onclick = function() {
    ins_popupOpen(txb_STRIP_MAJAGNT_INST_CD, txb_STRIP_MAJAGNT_INST_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_SRCH_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_SRCH_ISUR_CD, txb_SRCH_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_FROM_STD_CD_GRNT_DD_onclick = function() {
    popUpCalendar2(edt_FROM_STD_CD_GRNT_DD);
};
scwin.img_TO_STD_CD_GRNT_DD_onclick = function() {
    popUpCalendar2(edt_TO_STD_CD_GRNT_DD);
};
scwin.img_FROM_ISU_DD_onclick = function() {
    popUpCalendar2(edt_FROM_ISU_DD);
};
scwin.img_TO_ISU_DD_onclick = function() {
    popUpCalendar2(edt_TO_ISU_DD);
};
scwin.btn_modify_onclick = function() {
    // 수정
    //ins_Update();
    $c.win.alert("시스템 담당자에게 연락 바랍니다.");
};
scwin.btn_delete_onclick = function() {
    // 삭제
    //ins_Delete();
    $c.win.alert("시스템 담당자에게 연락 바랍니다.");
};
scwin.btn_search_onclick = function() {
    // 조회
    scwin.ins_Search();
};
scwin.trs_pwd_OnFail = function() {
    alert_tr_error(trs_pwd);
};
scwin.trs_pwd_OnSuccess = function() {
    $c.win.alert("비밀번호 초기화 완료 후 메일 발송 완료 하였습니다.");
};
scwin.txb_SRCH_STD_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_SRCH_STD_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_Search();
        } else {

        }
    }
};
